// ---------- ชีวิตในร่างอสูร ----------
const BZ=K=>!!K.beast;
def('bz_rival',{c:BZ,cd:3,w:6,go(K){C('🐾 จ่าฝูงท้าชิงถิ่น',`อสูรตัวผู้ขนาดใหญ่กว่าคุณครึ่งตัวยืนขวางลำธารที่คุณใช้ดื่มน้ำ มันขู่เสียงต่ำ ถ้าคุณถอย ถิ่นนี้เป็นของมัน`,[
 O('สู้',()=>skyMG('tap','🐾 ศึกชิงถิ่น','ฟาดให้ไวกว่า',sc=>{if(sc>=.45){K.cores++;K.f.beastTerr=(K.f.beastTerr|0)+1;say(`🩸 คู่แข่งถอยหนีเข้าป่า ถิ่นนี้เป็นของคุณ${xp(60)}`,'epic')}else zL(K,.3,'🩸 คุณถอยกลับเข้าถ้ำพร้อมแผลที่หลัง')}),'มินิเกม'),
 O('ใช้สติแบบคน ล่อมันเข้ากับดักพราน',()=>{if(rnd()<.6){K.cores+=2;say('🪤 อสูรตัวนั้นไม่เคยเจอศัตรูที่คิดแบบมนุษย์','epic')}else say('🙄 มันฉลาดกว่าที่คิด','')}),
 O('ถอยไปหาถิ่นใหม่',()=>say('🌲 ป่ายังกว้าง',''))])}});
def('bz_hunt',{c:BZ,cd:4,w:5,go(K){const kid=A(K).kid&&A(K).kid.end==='team'?A(K).kid.n:null;C('🎯 ทีมล่ามาถึง',`ทีมนักล่าห้าคนตามรอยคุณมาสามวัน ค่าหัวอสูรประหลาดตาเหมือนคนสูงพอจะซื้อบ้านได้${kid?` — คนที่ถือปืนหัวขบวนคือ${kid}`:K.f.team?' และคุณจำเสียงหัวเราะของหัวหน้าทีมได้ เขาเคยอยู่ทีมเดียวกับคุณ':''}`,[
 O('หนีเข้าป่าลึก',()=>skyMG('stealth','🌲 หลบทีมล่า','ขยับเฉพาะตอนพวกเขาไม่มอง',sc=>{if(sc>=.45)say('🌑 เสียงพวกเขาค่อยๆ หายไปในหมอก','');else zL(K,.35,'💥 กระสุนเจาะเกราะเฉียดหัวใจ')}),'มินิเกม'),
 O(kid?`ยืนนิ่งให้${kid}เห็นตา`:'เขียนชื่อตัวเองบนดินด้วยเล็บ',()=>{if(rnd()<(kid?.75:.45)){K.f.known=1;S.karma+=4;say(kid?`😢 ${kid}ลดปืนลง น้ำตาไหล “…จริงด้วย” แล้วสั่งทีมถอย ตั้งแต่นั้นทุกเดือนจะมีเนื้อสดวางไว้ที่ชายป่า`:'✍️ หัวหน้าทีมอ่านชื่อนั้นแล้วหน้าซีด เขาสั่งถอยทันที และไม่เคยรายงานเรื่องนี้','myth')}else zL(K,.4,'💥 พวกเขาคิดว่าเป็นกลลวงของอสูร')}),
 O('สู้ ใครล่าใครก็ได้',()=>{if(rnd()<.5){K.cores+=2;S.karma-=6;say('🩸 คุณกลับถ้ำพร้อมปืนสองกระบอกที่ไม่มีเจ้าของแล้ว','bad')}else zL(K,.5,'💥 ทีมนี้มืออาชีพ')})])}});
def('bz_wall',{c:BZ,cd:5,w:4,go(K){C('🧱 กำแพงบ้านเก่า',`คืนนี้คุณยืนบนเนินที่มองเห็น${K.city} ไฟบนกำแพงเรียงเป็นเส้นยาว ได้ยินเสียงประกาศเตือนภัยที่คุณเคยฟังทุกคืนตอนเป็นคน วันนี้เป็นวันเกิดคุณ`,[
 O('หอนยาวหนึ่งครั้ง',()=>{mindA(6);say('🌕 ทหารบนกำแพงหันมามอง ไม่มีใครยิง คุณเห็นใครบางคนโบกมือ','myth')}),
 O('แอบเข้าไปทางท่อระบายน้ำ',()=>{if(rnd()<.5){K.f.sneak=1;say('🏠 คุณมองผ่านหน้าต่างห้องเก่า ทุกอย่างยังเหมือนเดิม แม่ยังวางจานข้าวให้คุณทุกเย็น','myth')}else zL(K,.3,'🚨 สัญญาณเตือนดัง คุณหนีออกมาพร้อมกระสุนฝังขา')}),
 O('หันหลังกลับเข้าป่า',()=>say('🌲 บางบ้านกลับไปไม่ได้แล้ว',''))])}});
def('bz_pack',{c:K=>BZ(K)&&!K.f.pack,cd:4,w:4,go(K){C('🐺 ลูกกำพร้าสามตัว','ลูกหมาป่าเกราะสามตัวที่แม่ถูกนักล่าฆ่าตามคุณมาสองวัน มันไม่รู้ว่าคุณเป็นอะไร รู้แค่ว่าคุณไม่กินมัน',[
 O('เลี้ยงไว้ สร้างฝูง',()=>{K.f.pack=3;S.karma+=4;say('🐺 สามปีต่อมาคุณมีฝูงเจ็ดตัว ทุกตัวรู้ว่าห้ามเข้าใกล้กำแพงนคร เพราะคุณสอน','myth')}),
 O('ไล่ไป',()=>say('🐾 ลูกหมาป่ามองตามคุณนาน ก่อนวิ่งหายไป',''))])}});
def('bz_eat',{c:BZ,cd:3,w:5,go(K){C('🔶 แก่นอสูรในซาก','ซากอสูรระดับภูผาตายอยู่ในหุบ แก่นของมันยังเรืองแสง สัญชาตญาณร่างนี้บอกให้กลืน สติแบบคนบอกว่ายิ่งกิน ความเป็นคนยิ่งหาย',[
 O('กลืน',()=>{K.xp+=need(K)*1.2;advance();sync();K.f.beastLoss=(K.f.beastLoss|0)+1;say(`🔶 ร่างคุณใหญ่ขึ้นทั้งคืน ตื่นมาคุณจำชื่อแม่ไม่ได้อยู่ห้านาที${K.f.beastLoss>=3?' และครั้งนี้นานกว่าเดิม':''}`,'epic');if(K.f.beastLoss>=4&&rnd()<.3)queue('mad')}),
 O('ฝังแก่นไว้ ไม่กิน',()=>{mindA(10);say('🪨 คุณขุดหลุมด้วยกรงเล็บแล้วฝังมัน เหตุผลเดียวคือคนจะไม่ทำแบบนั้น','good')})])}});
def('bz_mirror',{c:BZ,cd:6,w:3,go(K){C('💧 เงาในน้ำ','คุณก้มดื่มน้ำแล้วเห็นเงาตัวเอง และนึกไม่ออกว่าก่อนหน้านี้หน้าตัวเองเป็นยังไง',[
 O('นั่งท่องชื่อตัวเองจนกว่าจะจำได้',()=>skyMG('mind','💧 ยึดความเป็นคน','อย่าให้สัญชาตญาณดึงจิตไป',sc=>{if(sc>=.5){mindA(12);K.f.beastLoss=Math.max(0,(K.f.beastLoss|0)-1);say(`🪞 “${S.name}” คุณจำได้ และจะไม่ลืมอีก`,'myth')}else{K.f.beastLoss=(K.f.beastLoss|0)+1;say('🌫️ ชื่อนั้นลอยหายไปกับลม','bad')}}),'มินิเกม'),
 O('ช่างมัน',()=>{K.f.beastLoss=(K.f.beastLoss|0)+1;say('🐾 คุณดื่มน้ำต่อ','')})])}});
def('bz_settle',{c:K=>BZ(K)&&zHas(K,'set')&&!(A(K).el&&A(K).el.burn),once:1,w:4,go(K){C('🦴 นิคมกระดูกวาฬ','คุณเดินไปถึงนิคมโดยไม่ได้ตั้งใจ ชายถือหอกตะโกนเตือนทุกคน แต่แม่เฒ่ากระดูกยกมือห้าม เธอมองตาคุณนาน “ข้าเคยเห็นตาแบบนี้มาก่อน… เจ้าเคยเป็นคน”',[
 O('ก้มหัวให้แม่เฒ่า',()=>{EL(K).tr+=20;K.f.setBeast=1;heal(.5);say('🔥 คืนนั้นคุณนอนข้างกองไฟของนิคม เด็กๆ เอาผ้าห่มมาคลุมหลังคุณ นิคมมีผู้พิทักษ์แล้ว','myth')}),
 O('ถอยกลับเข้าป่า',()=>say('🌲 คุณไม่อยากให้ใครต้องกลัว',''))])}});
def('bz_call',{c:K=>BZ(K)&&!K.f.beastCall,once:1,w:3,go(K){K.f.beastCall=1;C('☄️ เสียงเรียกในร่างอสูร','ในร่างนี้ เสียงจากดาวตกดังชัดกว่าตอนเป็นคนสิบเท่า มันไม่ได้เป็นตัวเลข มันเป็นเพลง และอสูรทั้งป่ากำลังเดินไปทางเดียวกัน',[
 O('เดินตามฝูงไปปล่องอุกกาบาต',()=>{K.f.star=1;K.xp+=need(K)*.8;advance();sync();say('🌌 ขอบปล่องมีอสูรนับพันนั่งเงียบ หันหน้าเข้าหาแสง คุณนั่งลงกับพวกมัน และเข้าใจบางอย่างที่ไม่มีภาษามนุษย์อธิบายได้'+zKnow(K,'crat'),'myth',true)}),
 O('ต้านเสียงไว้ อยู่ในป่า',()=>{mindA(12);say('🧠 คุณกัดหินจนฟันร้าวเพื่อไม่ให้ขาเดินตามเสียง','')})])}});
def('bz_wave',{c:K=>BZ(K)&&K.waveIn<=2,cd:6,w:6,go(K){C('🌊 คลื่นอสูรรอบใหม่',`ฝูงอสูรนับพันเริ่มรวมตัวในหุบ ทุกตัวหันหน้าไปทาง${K.city} คุณอยู่กลางฝูง และไม่มีใครรู้ว่าคุณเคยเป็นคน`,[
 O('เบนฝูงออกจากเส้นทาง',()=>{const p=cl(.3+K.mind/300+(K.f.pack?.15:0),.15,.85);if(rnd()<p){K.waveIn+=4;wallA(5);S.karma+=10;say('🐺 คุณวิ่งนำหน้าฝูงไปทางหุบผาตะวันตก คืนนั้นนครไม่ต้องเปิดไซเรน และไม่มีใครรู้ว่าทำไม','myth',true)}else zL(K,.4,'💢 ฝูงไม่ฟัง คุณถูกเหยียบผ่าน')},'ลุ้น'),
 O('วิ่งไปเตือนที่กำแพงก่อน',()=>{if(rnd()<.5){wallA(8);say('🚨 ทหารเห็นอสูรตัวเดียววิ่งมาหอนหน้าประตู ห้านาทีต่อมาไซเรนดัง นครพร้อมรับก่อนคลื่นถึงหนึ่งชั่วโมง','epic')}else zL(K,.35,'💥 ทหารยิงก่อนจะเข้าใจ')}),
 O('ไปกับฝูง',()=>{K.cores+=3;S.karma-=12;say('🔥 คืนนั้นคุณอยู่ฝั่งที่ไม่เคยคิดว่าจะได้อยู่','bad')})])}});
def('bz_silver',{c:K=>BZ(K)&&A(K).sv&&A(K).sv.st>=1,once:1,w:5,go(K){C('🦌 เขาเงินมาหา','เขาเงินยืนอยู่ปากถ้ำตอนรุ่งสาง มันไม่ได้มองคุณเหมือนมองคน มันมองเหมือนมองอสูรตัวหนึ่งที่เพิ่งเข้าใจ',[
 O('เดินตามมันไป',()=>{mindA(15);K.xp+=need(K)*.6;advance();sync();say('🌕 สามเดือนที่มันพาคุณเดินรอบป่า คุณเรียนรู้ว่าอสูรก็มีกฎ กินเท่าที่หิว ไม่ฆ่าลูกอ่อน ไม่ข้ามธารน้ำเงินด้วยกลิ่นเลือด'+zKnow(K,'spring'),'myth')}),
 O('ก้มหัวขอบคุณ แล้วอยู่ที่เดิม',()=>say('🦌 มันพยักหน้าครั้งเดียวแล้วหายไปในหมอก',''))])}});
// =================== ยุค 1 เติม: วัยเด็ก · ความรักและครอบครัว · ตามฤดู · พ่อแม่พี่น้อง · วัยชรา ===================
const FM=K=>K.fam||(K.fam={kids:[]});
const kid0=K=>K.rk<0&&!K.beast;
// ---------- วัยเด็กและวัยรุ่น ----------
def('k_wallsee',{c:K=>kid0(K)&&age()>=5&&age()<=9,once:1,w:4,go(K){C('🧱 ขึ้นกำแพงครั้งแรก','วันหยุดหนึ่ง พ่อพาคุณขึ้นบันไดเหล็กสามร้อยขั้นไปยืนบนกำแพงชั้นนอก ลมแรงจนต้องจับราว ไกลออกไปคือป่าสีเขียวเข้มสุดลูกหูลูกตา มีควันลอยขึ้นจากที่ไหนสักแห่ง',[
 O('ถามพ่อว่าข้างนอกมีใครอยู่ไหม',()=>{K.f.wonder=1;S.int+=2;say('👨 พ่อเงียบไปนาน “มีสิ แต่เราไม่พูดถึงพวกเขา” คุณจำประโยคนี้ได้จนโต','')}),
 O('ชี้ไปที่ควันแล้วบอกว่าโตขึ้นจะไปที่นั่น',()=>{K.f.wallVow=1;say('🌲 พ่อหัวเราะแล้วขยี้หัวคุณ แต่คืนนั้นคุณได้ยินพ่อคุยกับแม่เสียงเครียด','')}),
 O('กลัวจนร้องไห้',()=>say('😢 พ่ออุ้มคุณลงทันที ไม่ดุสักคำ',''))])}});
def('k_comic',{c:K=>kid0(K)&&age()>=7&&age()<=12,once:1,w:3,go(K){C('📚 การ์ตูนนักล่าแรงก์ S','การ์ตูนเล่มใหม่ของ “นักล่าเพลิงดารา” มาถึงร้านหนังสือ ทั้งห้องคุยแต่เรื่องนี้ ราคาเท่าค่าขนมคุณสามอาทิตย์',[
 O('เก็บเงินซื้อเอง',()=>{cr(-30);K.f.comic=1;say('📖 คุณอ่านจนปกขาด ท่อนที่พระเอกบอกว่า “กำแพงไม่ได้กันอสูร กำแพงกันความกลัว” คุณท่องได้','good')}),
 O(`ยืมจาก${K.np.bud}`,()=>{K.trust+=5;say(`🤝 ${K.np.bud}ให้ยืมแลกกับการที่คุณทำการบ้านเลขให้หนึ่งเดือน`,'')}),
 O('วาดการ์ตูนของตัวเอง',()=>{S.int+=3;say('✏️ การ์ตูนคุณมีพระเอกเป็นเด็กสลัมที่ไม่มียีน ครูประจำชั้นขอเก็บไว้หนึ่งเล่ม','good')})])}});
def('k_pill',{c:K=>kid0(K)&&age()>=10&&age()<=12,once:1,w:5,go(K){C('💊 ยาเพิ่มยีนหน้าโรงเรียน','ก่อนวันสอบวัดยีนหนึ่งเดือน มีพี่วัยรุ่นมาขายเม็ดยาสีม่วงหน้าโรงเรียน “กินวันละเม็ด ผลสอบขึ้นหนึ่งเกรดชัวร์” เพื่อนครึ่งห้องซื้อ',[
 O('ซื้อมากิน',()=>{if(rnd()<.6){hp(.2);K.f.pill='sick';say('🤢 คุณท้องเสียหนึ่งอาทิตย์ เม็ดยานั่นคือแป้งผสมสีย้อมผ้า','bad')}else{mutRoll(K,1);K.f.pill='mut';say('😵 คืนนั้นตัวคุณร้อนจี๋ ตื่นมามีบางอย่างเปลี่ยนไป','bad')}}),
 O('บอกครู',()=>{S.karma+=4;K.f.pill='rep';say('📣 พี่คนนั้นถูกจับ วันต่อมาเพื่อนสามคนไม่คุยกับคุณ แต่อีกสองคนแอบขอบคุณ','good')}),
 O('ไม่ซื้อ ฝึกวิ่งแทน',()=>{S.hp=Math.min(S.maxHp,S.hp+5);say('🏃 คุณวิ่งรอบสนามทุกเย็นจนวันสอบ อย่างน้อยก็หายใจทนขึ้น','')})])}});
def('k_sib',{c:K=>kid0(K)&&age()>=4&&age()<=9&&!FM(K).sib,once:1,w:4,go(K){const n=pick(['ข้าวปั้น','น้ำขิง','ต้นกล้า','ดาวเรือง','ก้อนหิน']);FM(K).sib={n,b:S.age};C('👶 น้องคนใหม่',`แม่คลอดน้องในหลุมหลบภัยคืนที่ไซเรนดัง น้องร้องไห้เสียงดังกว่าไซเรน ทุกคนในหลุมหัวเราะ พ่อตั้งชื่อเล่นน้องว่า “${n}”`,[
 O('สัญญาว่าจะปกป้องน้อง',()=>{K.f.sibVow=1;S.karma+=3;say(`🫶 คุณนั่งเฝ้าเปลของ${n}ทุกคืนที่ไซเรนดัง`,'good')}),
 O('น้อยใจที่แม่ไม่มีเวลาให้',()=>say(`😤 คุณงอนสามวัน จน${n}คว้านิ้วคุณไว้แน่นแล้วไม่ยอมปล่อย`,''))])}});
def('k_ration',{c:K=>kid0(K)&&(K.bg==='slum'||K.bg==='refugee')&&age()>=6&&age()<=12,cd:4,w:3,go(K){const s=FM(K).sib;C('🥫 อาหารปันส่วนถูกตัด','สภาตัดอาหารปันส่วนเขตนอกลงครึ่งหนึ่ง “ชั่วคราว” นี่เป็นเดือนที่สี่แล้ว แม่แบ่งข้าวให้คุณมากกว่าตัวเองทุกมื้อ',[
 O(s?`แบ่งข้าวตัวเองให้${s.n}`:'แบ่งข้าวคืนให้แม่',()=>{S.karma+=4;hp(.08);say('🍚 ท้องคุณร้องทั้งคืน แต่คุณยิ้มได้','good')}),
 O('แอบไปเก็บผักเรืองแสงข้างคลอง',()=>{if(rnd()<.7){cr(20);say('🥬 กินได้ แม้จะทำให้ปัสสาวะเรืองแสงไปสองวัน','')}else{mutRoll(K,.5);say('🤢 ผักบางต้นไม่ควรกิน','bad')}}),
 O('ไปยืนประท้วงกับผู้ใหญ่ที่หน้าสภา',()=>{K.f.slumTruth=1;S.int+=3;say('✊ คุณเป็นเด็กคนเดียวในฝูงคน มีนักข่าวถ่ายรูปคุณขึ้นหน้าหนึ่ง','epic')})])}});
def('k_teacher',{c:K=>kid0(K)&&age()>=8&&age()<=12,once:1,w:4,go(K){C('🧑‍🏫 ครูแขนเดียว','ครูพละคนใหม่มีแขนข้างเดียว เด็กๆ ลือว่าเคยเป็นนักล่าที่แขนขาดเพราะช่วยเด็กคนหนึ่ง วันหนึ่งเขาเห็นคุณนั่งหายใจหอบหลังวิ่ง',[
 O('ขอให้ครูสอนวิธีหายใจ',()=>{K.mind+=4;K.f.breath=1;say('🌬️ “หายใจเข้าสี่ กลั้นเจ็ด ออกแปด ตอนกลัวที่สุดให้ทำแบบนี้” คุณใช้มันไปทั้งชีวิต','good')}),
 O('ถามเรื่องแขนที่หายไป',()=>{S.int+=2;say('🫥 ครูยิ้ม “เด็กคนนั้นตอนนี้เป็นหมอแล้ว คุ้มนะ”','')})])}});
def('k_drill',{c:K=>kid0(K)&&age()>=6&&age()<=11,once:1,w:3,go(K){C('🚨 ซ้อมหนีภัยที่ไม่ใช่การซ้อม','ระหว่างซ้อมหนีภัยในโรงเรียน มีหนูยักษ์ฟันเหล็กตัวเท่าสุนัขหลุดเข้ามาจากท่อระบายน้ำ ครูยังอยู่อีกตึก เพื่อนตัวเล็กร้องไห้อยู่ข้างคุณ',[
 O('คว้าไม้ถูพื้นยืนบังเพื่อน',()=>{if(rnd()<.6){S.fame=(S.fame||0)+50;say('🧹 คุณฟาดจนมันวิ่งหนีกลับเข้าท่อ ทั้งโรงเรียนเรียกคุณว่า “นักล่าไม้ถูพื้น” จนจบ ป.6','epic')}else{hp(.2);say('🩸 มันกัดแขนคุณก่อนครูวิ่งมาถึง แผลเป็นนั้นคุณเรียกว่าใบอนุญาตใบแรก','')}}),
 O('พาเพื่อนปีนขึ้นตู้หนังสือ',()=>{S.karma+=3;say('📚 คุณสองคนนั่งบนตู้จนทหารมาถึง เพื่อนคนนั้นแบ่งขนมให้คุณทุกวันจนจบปี','good')})])}});
def('k_market',{c:K=>kid0(K)&&age()>=9&&age()<=12,once:1,w:3,go(K){C('🏪 แอบเข้าตลาดซาก','ตลาดซากอสูรห้ามเด็กเข้า แต่คุณลอดใต้แผงเข้าไปจนได้ กลิ่นเลือดกับน้ำมันเครื่องปนกัน นักล่าหน้าบากคนหนึ่งเห็นคุณจ้องแก่นอสูรในมือเขา',[
 O('ถามว่ามันอุ่นไหม',()=>{K.cores++;say('🔶 เขาหัวเราะแล้วโยนแก่นก้อนเล็กเท่าเม็ดถั่วให้ “อุ่นเหมือนหัวใจ เก็บไว้ อย่าบอกแม่” · แก่นอสูร +1','epic')}),
 O('วิ่งหนี',()=>say('🏃 คุณวิ่งออกมาโดยไม่หันหลัง แต่ฝันถึงแสงแก่นอสูรทั้งคืน',''))])}});
def('k_parhurt',{c:K=>kid0(K)&&age()>=8&&age()<=13&&K.bg!=='hunter',once:1,w:3,go(K){C('🏭 อุบัติเหตุที่โรงงาน','เครื่องอัดปลอกกระสุนที่โรงงานระเบิด แม่มือขวาเจ็บหนัก ทำงานไม่ได้สามเดือน บ้านไม่มีเงินเก็บ',[
 O('ไปรับจ้างล้างจานหลังเลิกเรียน',()=>{cr(120);S.karma+=4;say('🍽️ มือคุณเปื่อยทุกคืน แต่ค่าเช่าบ้านไม่ขาดสักเดือน','good')}),
 O('ทำกับข้าวดูแลแม่',()=>{S.karma+=3;S.int+=2;say('🍳 ไข่เจียวคุณไหม้ทุกจาน แม่กินหมดทุกจาน','good')})])}});
def('k_radio',{c:K=>kid0(K)&&age()>=10&&age()<=13,once:1,w:2,go(K){C('📻 วิทยุจากกองขยะ',`คุณกับ${K.np.bud}ประกอบวิทยุจากซากรถทหาร หมุนคลื่นไปเจอเสียงพูดภาษาที่ไม่รู้จัก ปนกับเสียงคล้ายวาฬร้อง`,[
 O('อัดเสียงเก็บไว้',()=>{K.f.ai=1;S.int+=3;say('📼 เทปม้วนนั้นอยู่ในลิ้นชักคุณไปอีกหลายสิบปี','')}),
 O('เอาไปให้ครูวิทยาศาสตร์ฟัง',()=>{S.int+=2;say('👩‍🔬 ครูฟังแล้วหน้าซีด ขอยึดวิทยุไว้ และไม่เคยคืน','')})])}});
def('k_aftertest',{c:K=>K.rk>=0&&!K.beast&&age()<=15&&K.seen.k_test,once:1,w:8,go(K){const hi='SA'.includes(K.talK),lo='FE'.includes(K.talK);C('📋 หลังผลสอบยีน',hi?'ชื่อคุณขึ้นป้ายหน้าโรงเรียน ครูใหญ่มาเยี่ยมบ้าน ตระกูลใหญ่ส่งจดหมายเชิญ พ่อแม่ไม่รู้จะดีใจหรือกลัว':lo?'ผลคุณอยู่ท้ายกระดาน เพื่อนบางคนเลิกนั่งข้างคุณ ครูประจำชั้นพูดว่า “ไม่เป็นไร โลกต้องการช่างซ่อมกำแพงด้วย”':'ผลคุณอยู่กลางๆ ไม่มีใครพูดถึง ซึ่งก็แปลว่าไม่มีใครมาคาดหวัง',[
 hi?O('ปฏิเสธตระกูลใหญ่ อยู่กับครอบครัว',()=>{S.karma+=4;say('🏠 แม่ทำแกงไก่ฉลอง ทั้งตึกได้กลิ่น','good')}):O('ตั้งใจฝึกเป็นสองเท่า',()=>{K.xp+=need(K)*.5;say(`🔥 คุณตื่นตีห้าทุกวัน${lo?' ครูแขนเดียวเห็นแล้วพยักหน้า':''}`,'good')}),
 O('ทำเหมือนไม่มีอะไรเกิดขึ้น',()=>{K.mind+=3;say('🧘 คุณเริ่มเข้าใจว่าตัวเลขบนกระดาษไม่ใช่ตัวคุณ','')})])}});
def('k_teenwall',{c:K=>!K.beast&&age()>=14&&age()<=16,once:1,w:4,go(K){C('🎒 อาสาขนกระสุน','นครเปิดรับอาสาสมัครอายุสิบสี่ขึ้นไปช่วยขนกระสุนขึ้นกำแพงช่วงซ้อมใหญ่ คุณได้ยืนข้างทหารจริงเป็นครั้งแรก ทหารคนนั้นอายุมากกว่าคุณแค่สามปี',[
 O('ถามเขาว่ากลัวไหม',()=>{K.mind+=3;say('🪖 “ทุกคืน” เขาตอบ “แต่ข้างหลังข้ามีน้องสาว” สามปีต่อมาคุณเห็นชื่อเขาบนแผ่นป้ายผู้เสียชีวิต','myth')}),
 O('ขนให้ได้มากที่สุดในรุ่น',()=>{S.hp=Math.min(S.maxHp,S.hp+5);S.fame=(S.fame||0)+30;say('📦 จ่าบนกำแพงจดชื่อคุณไว้ในสมุด “คนนี้ให้มาสอบทหาร”','good')})])}});

// ---------- ความรักและครอบครัว ----------
const LOV=[['ช่างซ่อมกำแพง','มือเปื้อนปูน หัวเราะเสียงดัง และรู้จักทุกรอยร้าวบนกำแพงชั้นนอก'],['พยาบาลคลินิกสลัม','ใจเย็นแบบคนที่เห็นคนตายมาเยอะ และยังเลือกจะยิ้ม'],['นักล่าทีมอื่น','เคยแย่งรังอสูรกับคุณสามครั้ง ชนะสองครั้ง'],['ครูโรงเรียนเขตนอก','สอนเด็กอ่านหนังสือด้วยการ์ตูนนักล่า'],['คนส่งของข้ามเขต','ขี่มอเตอร์ไซค์ผ่านทุกด่านโดยไม่เคยโดนตรวจ ไม่มีใครรู้ว่าทำได้ยังไง']];
def('fam_meet',{c:K=>ok(K)&&age()>=20&&age()<=45&&!S.spouse&&!FM(K).p&&(!K.f.love||K.f.love==='no'),cd:4,w:4,go(K){const L=pick(LOV),n=pick(FN.filter(x=>x!==S.name&&x!==K.np.bud&&x!==K.np.rv));C('💞 คนที่ทำให้หยุดมอง',`${n} — ${L[0]} ${L[1]} คุณเจอกันครั้งที่สามในสัปดาห์นี้แล้ว ${pick(['ที่ร้านบะหมี่หน้าสมาคม','ใต้กำแพงตอนไฟดับ','ที่ตลาดซากตอนฝนตก'])}`,[
 O('ชวนคุย',()=>{FM(K).p=n;FM(K).job=L[0];FM(K).st=1;say(`☕ คุยกันจนร้านปิด ${n}หัวเราะกับมุกห่วยๆ ของคุณทุกมุก`,'good');later(K,'fam_date',1)}),
 O('ยังไม่พร้อม ชีวิตนักล่าอันตรายเกินไป',()=>{FM(K).skip=(FM(K).skip|0)+1;say('🚶 คุณเดินผ่านไป แต่ยังหันกลับไปมอง','')})])}});
def('fam_date',{c:()=>false,w:0,go(K){const F=FM(K);if(!F.p||!ok(K))return;C(`🌙 คืนไฟดับกับ${F.p}`,`ไฟดับทั้งเขตสามชั่วโมง ${F.p}ชวนคุณขึ้นดาดฟ้าตึกที่สูงที่สุดในเขตนอก ไม่มีแสงไฟในนคร เป็นครั้งแรกที่คุณเห็นดาวเต็มฟ้า`,[
 O('เล่าความฝันให้ฟัง',()=>{F.st=2;mindA(5);say(`🌌 คุณบอกว่าอยากรู้ว่าดาวตกมาจากไหน ${F.p}บอกว่าอยากเห็นโลกที่ไม่มีกำแพง คืนนั้นทั้งคู่จับมือกันโดยไม่มีใครพูดอะไร`,'myth');later(K,'fam_fear',2)}),
 O('ชี้ดาวแล้วตั้งชื่อให้มั่วๆ',()=>{F.st=2;say(`😆 ${F.p}หัวเราะจนน้ำตาไหลตอนคุณตั้งชื่อกลุ่มดาวว่า “หม้อก๋วยเตี๋ยวใหญ่”`,'good');later(K,'fam_fear',2)})])}});
def('fam_fear',{c:()=>false,w:0,go(K){const F=FM(K);if(!F.p||!ok(K))return;C('😟 ทุกครั้งที่ประตูนครเปิด',`${F.p}ยืนรอที่ประตูนครทุกครั้งที่คุณออกล่า และนับหัวนักล่าที่กลับมา คืนนี้${F.p}ร้องไห้ “ฉันนับไม่ถึงชื่อเธอไปสองชั่วโมง”`,[
 O('สัญญาว่าจะกลับมาเสมอ',()=>{F.st=3;F.prom=1;say('🤞 คุณผูกด้ายแดงที่ข้อมือก่อนออกล่าทุกครั้งตั้งแต่วันนั้น','good');later(K,'fam_wed',1)}),
 O('ชวนให้มาเรียนเป็นนักล่าด้วยกัน',()=>{if(rnd()<.5){F.st=3;F.hunt=1;K.f.team=1;K.team=(K.team|0)+1;say(`🗡️ ${F.p}ฝึกจนสอบผ่าน ตอนนี้ไม่ต้องรอที่ประตูอีกแล้ว`,'epic');later(K,'fam_wed',1)}else{say(`😔 ${F.p}ส่ายหัว “ฉันไม่ได้อยากสู้ ฉันอยากให้เธอเลิกสู้”`,'');later(K,'fam_break',2)}}),
 O('บอกว่าถ้ากลัวขนาดนี้ อย่ารอเลย',()=>{F.st=0;F.p=null;say('💔 คืนนั้นเป็นคืนสุดท้าย','bad')})])}});
def('fam_break',{c:()=>false,w:0,go(K){const F=FM(K);if(!F.p||!ok(K)||S.spouse)return;C('💔 ทางแยก',`${F.p}ได้งานที่นครกระจกเชียงใหม่ ไกลจากที่นี่สิบวันเดินทาง “ไปด้วยกันไหม ที่นั่นกำแพงสูงกว่า”`,[
 O('ไปด้วย',()=>{const o=pick(CITY.filter(x=>x!==K.city));K.city=o;F.st=3;say(`🚚 คุณย้ายไป${o} นักล่าที่นั่นไม่รู้จักชื่อคุณ คุณเริ่มใหม่หมด`,'epic');later(K,'fam_wed',1)}),
 O('ขอให้อยู่ด้วยกันที่นี่',()=>{if(rnd()<.5){F.st=3;say(`🫂 ${F.p}ฉีกจดหมายรับงานต่อหน้าคุณ`,'myth');later(K,'fam_wed',1)}else{F.p=null;F.st=0;say('🚉 คุณไปส่งที่ประตูนครตอนเช้ามืด','bad')}},'50%'),
 O('ปล่อยให้ไป',()=>{F.p=null;F.st=0;mindA(5);say('🌅 บางคนเข้ามาเพื่อสอนให้เรารู้ว่าเราต้องการอะไร','')})])}});
def('fam_wed',{c:()=>false,w:0,go(K){const F=FM(K);if(!F.p||!ok(K)||S.spouse)return;C('💍 คำถามบนกำแพง',`คุณพา${F.p}ขึ้นกำแพงตอนพระอาทิตย์ตก แหวนในกระเป๋าทำจากแก่นอสูรก้อนแรกที่คุณล่าได้ ขัดจนใส`,[
 O('คุกเข่าขอแต่งงาน',()=>{S.spouse=F.p;F.st=4;F.wy=S.age;S.karma+=4;const big=(S.fame||0)>=1500;say(big?`💒 งานแต่งของนักล่าดังทั้งนครมาร่วม แต่ช่วงที่${F.p}ร้องไห้คือตอนเด็กสลัมสิบคนร้องเพลงที่ซ้อมมาให้`:`💒 งานเล็กๆ บนดาดฟ้าตึก มีโต๊ะห้าตัว ข้าวผัดสามกระทะ และทุกคนที่สำคัญ`,'myth',true);try{keyAdd(`${S.age} ปี — แต่งงานกับ${F.p}`)}catch(e){}later(K,'fam_baby',2)}),
 O('ยังไม่ขอ แค่ยืนดูพระอาทิตย์ด้วยกัน',()=>{say('🌇 แหวนยังอยู่ในกระเป๋า อีกปีหนึ่งก็ได้','');later(K,'fam_wed',2)})])}});
def('fam_baby',{c:()=>false,w:0,go(K){const F=FM(K);if(!S.spouse||!ok(K))return;const n=pick(['ฟ้าใส','ดาวเหนือ','กำแพง','ภูผา','น้ำฝน','รุ่งอรุณ']);C('👶 เสียงร้องในหลุมหลบภัย',`${S.spouse}เจ็บท้องคืนที่ไซเรนดัง ลูกคลอดในหลุมหลบภัยแบบเดียวกับที่คุณเคยเกิด เสียงร้องดังกว่าไซเรน ทุกคนในหลุมหัวเราะ`,[
 O(`ตั้งชื่อว่า “${n}”`,()=>{F.kids.push({n,b:S.age});S.kids=(S.kids|0)+1;S.karma+=3;say(`👶 <b>${n}</b> ลืมตาครั้งแรกตอนไฟในหลุมกะพริบ`,'myth',true);try{keyAdd(`${S.age} ปี — ${n}เกิด`)}catch(e){}}),
 O('ให้คนทั้งหลุมช่วยตั้งชื่อ',()=>{const m='ไซเรน';F.kids.push({n:m,b:S.age});S.kids=(S.kids|0)+1;say('😂 มติเอกฉันท์ ลูกคุณชื่อ “ไซเรน”','good')})])}});
def('fam_baby2',{c:K=>ok(K)&&S.spouse&&FM(K).kids.length<3&&age()<=50,cd:5,w:3,go(K){const F=FM(K);C(F.kids.length?'🍼 สมาชิกใหม่?':'🍼 บ้านที่มีเสียงเด็ก',F.kids.length?`${S.spouse}ถามขณะที่${F.kids[0].n}หลับอยู่บนตัก “บ้านนี้ยังมีที่ว่างอีกคนไหม”`:`${S.spouse}มองเด็กๆ วิ่งเล่นใต้ตึกนานกว่าปกติ แล้วหันมาถามคุณเบาๆ “เราจะเลี้ยงเด็กสักคนในโลกแบบนี้ได้ไหม”`,[
 O('มีเสมอ',()=>{const n=pick(['ใบข้าว','เมฆ','ทรายแก้ว','หิ่งห้อย','ลมหนาว']);F.kids.push({n,b:S.age+1});S.kids=(S.kids|0)+1;say(`👶 ปีต่อมา <b>${n}</b> เกิดตอนเช้าที่ไม่มีไซเรนเลยสักเสียง`,'good')}),
 O('ตอนนี้พอแล้ว',()=>say('🏠 บ้านเล็กๆ นี้อบอุ่นพอแล้ว',''))])}});
def('fam_kidtest',{c:K=>ok(K)&&FM(K).kids.some(k=>S.age-k.b>=12&&!k.t),w:8,go(K){const k=FM(K).kids.find(x=>S.age-x.b>=12&&!x.t);if(!k)return;k.t=pick(['S','A','B','C','D','E','F']);const hi='SA'.includes(k.t),lo='EF'.includes(k.t);C(`🧬 วันสอบยีนของ${k.n}`,`คุณนั่งแถวผู้ปกครองในหอประชุมเดียวกับที่คุณเคยสอบ ${k.n}เดินขึ้นเวทีโดยไม่หันมามอง เครื่องสแกนกะพริบ <b>${k.t}</b>`,[
 O(hi?'กอดแล้วบอกว่าภูมิใจ':'กอดแล้วบอกว่าภูมิใจเหมือนเดิม',()=>{S.karma+=2;mindA(4);say(hi?`🌟 ${k.n}ยิ้มจนตาหยี “ต่อไปหนูจะแซงพ่อแม่”`:`🫂 ${k.n}ร้องไห้ในอ้อมกอดคุณ แล้วพูดว่า “ไม่ได้ร้องเพราะเสียใจนะ”`,'good')}),
 lo?O('สอนเองที่บ้าน ไม่ง้อโรงฝึก',()=>{k.tr=1;say(`🗡️ ทุกเย็นในลานหลังตึก คุณสอน${k.n}เหมือนที่ใครบางคนเคยสอนคุณ`,'epic')}):O('ไม่ให้ไปโรงเรียนนักล่า',()=>{k.civ=1;say(`📚 ${k.n}งอนหนึ่งเดือน แล้วไปสมัครเรียนวิศวะกำแพงแทน`,'')})].filter(Boolean))}});
def('fam_kidhunt',{c:K=>ok(K)&&FM(K).kids.some(k=>S.age-k.b>=17&&k.t&&!k.civ&&!k.path),w:5,go(K){const k=FM(K).kids.find(x=>S.age-x.b>=17&&x.t&&!x.civ&&!x.path);if(!k)return;C(`🗡️ ${k.n}สอบใบอนุญาตนักล่า`,`${k.n}ยื่นใบสมัครสอบใบอนุญาตโดยไม่บอกคุณก่อน คุณรู้จากรายชื่อที่สมาคมส่งมาให้เซ็นในฐานะผู้ปกครอง`,[
 O('เซ็นให้ แล้วไปเชียร์',()=>{k.path='hunter';if(rnd()<.65){fameA(300);say(`🪪 ${k.n}สอบผ่าน! ใบอนุญาตใบแรกถูกใส่กรอบไว้ข้างใบของคุณ`,'myth')}else say(`😓 ${k.n}สอบตก และขอสอบใหม่ปีหน้า คุณรู้ว่าจะไม่มีวันห้ามได้`,'')}),
 O('ชวนเข้าทีมตัวเอง',()=>{k.path='team';K.f.team=1;K.team=(K.team|0)+1;say(`🛡️ ${k.n}เข้าทีมคุณ ทุกครั้งที่ออกล่า คุณเผลอยืนบังลูกโดยไม่รู้ตัว`,'epic')}),
 O('ไม่เซ็น',()=>{k.path='no';say(`🚪 ${k.n}ไม่คุยกับคุณสามเดือน แล้ววันหนึ่งก็ไปสมัครเป็นทหารแทน`,'bad')})])}});
def('fam_crisis',{c:K=>ok(K)&&S.spouse,cd:9,w:3,go(K){C('🏚️ ตึกถล่ม',`แผ่นดินไหวจากอสูรใต้ดินทำให้ตึกที่ทำงานของ${S.spouse}ถล่ม หน่วยกู้ภัยบอกว่าต้องรออุปกรณ์หกชั่วโมง`,[
 O('มุดเข้าไปเอง',()=>skyMG('stealth','🏚️ มุดใต้ซากตึก','ขยับตอนซากหยุดสั่น',sc=>{if(rnd()<cl(.4+sc*.55,.1,.95)){S.karma+=5;say(`🫂 คุณลาก${S.spouse}ออกมาพร้อมคนอีกสามคน มือคุณเลือดออกทุกนิ้ว ไม่มีใครสนใจ`,'myth')}else{zL(K,.35,'🧱 ซากถล่มทับขาคุณ หน่วยกู้ภัยต้องช่วยออกมาทั้งสองคน')}}),'มินิเกม'),
 O('ยกแผ่นปูนด้วยพลังกาย',()=>{if(K.rk>=3||rnd()<.4){fameA(500);say(`💪 แผ่นปูนสามตันยกขึ้นในมือคุณ คนทั้งถนนเงียบ ${S.spouse}คลานออกมาแล้วหัวเราะทั้งน้ำตา`,'epic')}else zL(K,.3,'💥 กล้ามเนื้อคุณฉีก แต่ก็ยกได้พอให้ลอดออก')})])}});
def('fam_anniv',{c:K=>ok(K)&&S.spouse&&FM(K).wy!=null&&S.age-FM(K).wy>=5,cd:7,w:3,go(K){const y=S.age-FM(K).wy;C(`💐 ครบรอบ ${y} ปี`,`${S.spouse}ลืมวันครบรอบ ทั้งที่ทุกปีเป็นคนจำได้คนเดียว วันนี้มัวแต่ทำงานจนดึก`,[
 O('เตรียมอาหารรอที่บ้าน',()=>{heal(.2);S.karma+=2;say('🍲 คุณทำอาหารจานแรกที่เคยกินด้วยกัน บะหมี่หน้าสมาคม รสชาติแย่กว่าร้านมาก ทั้งคู่กินหมด','good')}),
 O('พาขึ้นดาดฟ้าดูดาวเหมือนคืนแรก',()=>{mindA(5);say('🌌 กลุ่มดาว “หม้อก๋วยเตี๋ยวใหญ่” ยังอยู่ที่เดิม','myth')})])}});
def('fam_old',{c:K=>ok(K)&&S.spouse&&age()>=70,cd:12,w:3,go(K){C('👵 แก่ไปด้วยกัน',`ผม${S.spouse}ขาวหมดแล้ว ส่วนคุณยังดูหนุ่มกว่าอายุจริงเพราะยีน คนแปลกหน้าบางคนคิดว่าคุณเป็นลูก`,[
 O('หาทางยืดอายุให้คู่ชีวิต',()=>{if(S.money>=20000){cr(-20000);say('💉 เซรั่มยืดอายุจากเขตชั้นในซื้อเวลาเพิ่มได้สิบปี สิบปีที่คุ้มทุกวัน','good')}else say('💸 ราคาเซรั่มยืดอายุสูงเกินกว่าที่นักล่าจะจ่ายไหว','')}),
 O('ยอมรับเวลาที่เหลือ',()=>{mindA(8);say('🪑 คุณสองคนนั่งริมกำแพงทุกเย็น นับรถบรรทุกที่กลับเข้านคร','myth')})])}});
def('fam_loss',{c:K=>ok(K)&&S.spouse&&age()>=78&&rnd()<.3,once:1,w:4,go(K){const p=S.spouse;C(`🕯️ ${p}จากไป`,`${p}จากไปอย่างสงบตอนเช้ามืด มือยังจับมือคุณอยู่ บนโต๊ะข้างเตียงมีด้ายแดงเส้นใหม่วางไว้ เหมือนทุกครั้งก่อนคุณออกล่า`,[
 O('ผูกด้ายแดงเส้นสุดท้าย',()=>{S.spouse=null;mindA(15);try{keyAdd(`${S.age} ปี — ${p}จากไป`)}catch(e){}say('🧵 คุณไม่เคยแก้ด้ายเส้นนั้นออกอีกเลย','myth',true)})])}});

// ---------- ตามฤดู ----------
def('s_memorial',{c:K=>!K.beast&&age()>=6,cd:8,w:3,go(K){C('🕯️ วันรำลึกดาวตก','วันที่สิบเจ็ดเดือนเจ็ด ทั้งนครดับไฟหนึ่งนาที แล้วจุดเทียนเรียงบนกำแพงยาวสามสิบกิโล ปีนี้นครขอให้คุณเป็นคนจุดเทียนเล่มแรก',[
 O('จุดเทียนให้คนที่จากไป',()=>{mindA(5);S.karma+=2;say('🕯️ เปลวเทียนสามหมื่นเล่มไหวพร้อมกันตามลม จากนอกกำแพง มันคงดูเหมือนดาว','myth')}),
 O('จุดเทียนให้อสูรที่ตายด้วยมือคุณ',()=>{mindA(8);say('🕯️ ไม่มีใครเข้าใจว่าทำไม แต่เด็กคนหนึ่งจุดตามคุณ','')})])}});
def('s_songkran',{c:K=>!K.beast&&age()>=5,cd:7,w:3,go(K){C('💦 สงกรานต์ปีน้ำปันส่วน','น้ำในนครปันส่วนวันละสองถัง สงกรานต์ปีนี้สภาห้ามเล่นน้ำ แต่เด็กๆ ในสลัมเอาน้ำล้างจานผสมสีมาสาดกันอยู่ดี',[
 O('ร่วมวงเล่น',()=>{S.karma+=2;heal(.1);say('🎉 คุณเปียกไปทั้งตัวด้วยน้ำสีชมพูกลิ่นน้ำยาล้างจาน และหัวเราะดังที่สุดในรอบปี','good')}),
 O('ขนน้ำจากธารนอกกำแพงมาให้เด็กเล่น',()=>{if(K.lic>=1||K.rk>=1){S.karma+=6;fameA(150);say('🚰 ถังน้ำร้อยถังจากนอกกำแพง สลัมได้เล่นสงกรานต์จริงครั้งแรกในรอบสิบปี','myth')}else say('🚫 ทหารไม่ให้เด็กไม่มีใบอนุญาตออกนอกประตู','')}),
 O('รดน้ำดำหัวคนแก่ในตึก',()=>{S.karma+=3;say('👵 ยายชั้นสามให้พรว่า “ขอให้กลับบ้านทุกครั้งที่ออกไป”','good')})])}});
def('s_loy',{c:K=>!K.beast&&age()>=6,cd:7,w:3,go(K){C('🪷 ลอยกระทงในคลองระบายน้ำ','คลองเดียวในนครคือคลองระบายน้ำที่ไหลลอดกำแพงออกไปข้างนอก คนในนครลอยกระทงที่นี่ เชื่อกันว่ากระทงจะลอยไปถึงคนที่อยู่ข้างนอก',[
 O('ขอให้คนที่หายไปได้เห็น',()=>{mindA(4);say(`🪷 กระทงใบเล็กของคุณลอดใต้กำแพงไป${K.par&&K.par.st==='miss'?' คุณเขียนชื่อพ่อไว้บนใบตอง':''}`,'myth')}),
 O('ขอให้ได้ออกไปเห็นโลกข้างนอก',()=>{K.f.wallVow=1;say('🌙 เด็กข้างๆ ขอเหมือนคุณเป๊ะ สองคนหัวเราะใส่กัน','')})])}});
def('s_newyear',{c:K=>!K.beast&&age()>=8,cd:8,w:2,go(K){C('🎆 พลุปีใหม่ต้องห้าม','พลุเป็นของต้องห้ามเพราะเสียงและแสงดึงอสูร แต่เด็กวัยรุ่นกลุ่มหนึ่งแอบจุดบนดาดฟ้าเขตนอก สามนาทีต่อมามีเสียงหอนตอบมาจากป่า',[
 O(K.rk>=1?'ขึ้นกำแพงเฝ้าจนรุ่งเช้า':'ช่วยดับไฟพลุ',()=>{S.karma+=3;if(K.rk>=1){wallA(2);say(`🛡️ ฝูงหมาป่ามาถึงตอนตีสอง คุณกับทหารสี่คนเฝ้าจนมันถอย${xp(20)}`,'epic')}else say('🧯 คุณกับเพื่อนสาดน้ำดับไฟพลุ แล้ววิ่งหนีทหารกันทั้งแก๊ง','')}),
 O('แอบดูพลุจนจบ',()=>{mindA(3);say('🎇 ดอกไม้ไฟสีทองบานกลางฟ้าดำ สวยจนคุณลืมกลัวไปชั่วครู่','')})])}});
def('s_migr',{c:K=>!K.beast&&K.lic>=1,cd:5,w:3,go(K){C('🦬 ฤดูอพยพอสูร','ฤดูแล้งมาถึง ฝูงอสูรกินพืชหลายหมื่นตัวเดินผ่านทุ่งซากรถมุ่งลงใต้ พื้นดินสั่นทั้งวัน สมาคมเปิดฤดูล่า และเตือนว่านักล่าตายมากที่สุดในเดือนนี้',[
 O('ล่าตามขอบฝูง',()=>skyMG('tap','🦬 ล่าตัวที่หลุดฝูง','แตะตัวที่หลุดออกมาให้ทัน',sc=>{if(sc>=.45){K.cores+=2;say(`🦬 ฤดูนี้คุณเก็บแก่นได้มากกว่าทั้งปีที่แล้ว ${cr(2000+K.rk*800)}`,'good');tqUse(K,['กาย','ยีน'],1,'iron')}else zL(K,.3,'🦬 ฝูงเปลี่ยนทิศ คุณเกือบถูกเหยียบ')}),'มินิเกม'),
 O('ขึ้นหอดูฝูงเฉยๆ',()=>{mindA(4);say('🔭 ฝูงยาวสุดสายตา ไม่มีตัวไหนสนใจนครเลยสักตัว คุณนึกขึ้นได้ว่าโลกนี้ไม่ได้หมุนรอบมนุษย์','')})])}});
def('s_acid',{c:K=>!K.beast&&age()>=10,cd:6,w:3,go(K){C('🌧️ ฤดูฝนกรด','ฝนจากเขตอุกกาบาตกัดหลังคาสังกะสีในสลัมเป็นรูพรุนทุกปี ปีนี้หนักกว่าเดิม บ้านหลายหลังน้ำท่วมถึงเข่า',[
 O('ปีนขึ้นซ่อมหลังคาให้เพื่อนบ้าน',()=>{S.karma+=5;hp(.05);say('🔧 มือคุณพองเพราะกรด แต่หลังคาสิบหลังไม่รั่วแล้ว','good')}),
 O(`บริจาคแผ่นหลังคาเคลือบ (${crT(2000)})`,()=>{if(S.money<2000)return say('💸 เงินไม่พอ','');cr(-2000);S.karma+=6;fameA(100);say('🏚️ หลังคาเคลือบสีเงินสะท้อนแดดทั้งซอย คนเรียกซอยนั้นตามชื่อคุณ','good')}),
 O('อยู่ในห้อง',()=>{})])}});
def('s_harvest',{c:K=>!K.beast&&age()>=5,cd:7,w:2,go(K){C('🌾 เทศกาลเก็บเกี่ยวในโรงเรือน','โรงเรือนปลูกผักใต้กำแพงชั้นในเก็บเกี่ยวรอบใหญ่ นครแจกผักสดให้ทุกบ้านคนละหนึ่งตะกร้า ปีละครั้งที่คนเขตนอกได้กินผักไม่เรืองแสง',[
 O('เอาตะกร้าไปให้ครอบครัวในสลัม',()=>{S.karma+=4;say('🥬 คุณกินบะหมี่ซองเปล่าๆ ในคืนนั้นอย่างมีความสุข','good')}),
 O('ทำแกงเลี้ยงทั้งตึก',()=>{heal(.15);S.karma+=3;say('🍛 หม้อแกงใบใหญ่ที่สุดในตึกหมดในยี่สิบนาที','good')})])}});
def('s_blackout',{c:K=>!K.beast&&age()>=8,cd:8,w:2,go(K){C('🔌 ไฟดับสามวัน','สถานีไฟฟ้านครเสีย ไฟดับทั้งเขตนอกสามวัน กลางคืนมืดสนิท ได้ยินเสียงหอนชัดกว่าทุกครั้ง คนในตึกออกมานั่งรวมกันที่โถงบันได',[
 O('เล่าเรื่องผีให้เด็กๆ ฟัง',()=>{S.karma+=2;say('👻 เด็กๆ กรี๊ดจนคนชั้นบนลงมาดู แล้วก็นั่งฟังด้วย','good')}),
 O(K.rk>=1?'ไปเฝ้าสถานีไฟฟ้าทั้งคืน':'ถือเทียนเดินส่งคนแก่ขึ้นห้อง',()=>{S.karma+=4;if(K.rk>=1)say(`⚡ คุณจับขโมยสายไฟได้สองคนในคืนที่สอง${xp(15)}`,'');else say('🕯️ ยายชั้นห้าให้ขนมปังแข็งๆ มาหนึ่งก้อน','good')})])}});

// ---------- พ่อแม่และพี่น้อง ----------
