const eraN=()=>{const K=SK();try{const e_=uEra(K);if(e_)return ERAS[e_-1]}catch(x){}return K&&K.rk>=14&&K.gx&&K.gx.out&&ERAS[3]?ERAS[3]:K&&K.rk>=10&&K.sp&&ERAS[2]?ERAS[2]:e2(K)?ERAS[1]:ERAS[0]};
