defA('an_dream',{c:K=>AN(K).st>=3,cd:4,w:3,go(K){const L=['คุณฝันว่าเป็นดาวทั้งดวง มีเมล็ดเล็กๆ ไหลอยู่ในเส้นเลือดที่เป็นแม่น้ำ','คุณฝันเห็นเผ่าผู้หว่านเมล็ดโบกมือลาโลกก่อนมีมนุษย์ ไม่มีใครหันกลับมามอง','คุณฝันเห็นเรือดำขนาดเท่าดวงจันทร์จอดนิ่งหลังดาวพฤหัส มันรออยู่','คุณฝันว่าญาณเป็นเด็กผู้หญิงผมสั้นนั่งข้างเตียง ถามว่าคุณกลัวความตายไหม'];say(`🌌 ${pick(L)}`,'myth');mindA(2)}});
