function ctStep(K){const n=AN(K),T=n.ct,ST=[['quiz','🧮 ด่านที่ 1: ตรรกะ','ตอบให้ทันเวลา'],['grid','🔲 ด่านที่ 2: ความจำ','จำช่องที่เรืองแสง'],['beat','🎵 ด่านที่ 3: หัวใจ','แตะตามจังหวะหัวใจของดาว']];const st=ST[T.i];
 mgD(st[0],2+Math.floor(keyN(K)/2),st[1],st[2],sc=>{T.s+=sc;T.i++;say(`${st[1]} — ${sc>=.5?'✅ ผ่าน':'⚠️ เฉียด'}`,sc>=.5?'good':'');if(T.i<3)return setTimeout(()=>ctStep(K),500);
  if(T.s>=1.6){n.core=1;say('🌌 ประตูเปิด ข้างในไม่ใช่ห้อง แต่เป็นท้องฟ้าทั้งผืน ญาณเปิดภาพให้ดู: เรือดำยาวพันกิโลเมตรลอยนิ่งหลังดาวพฤหัส “ผู้หว่านเมล็ดคนสุดท้ายกำลังกลับมาเก็บเกี่ยว และสิ่งที่เขาจะเก็บ คือทุกเซลล์ที่งอกแล้วบนโลกนี้ รวมถึงเจ้า”','myth',true);try{keyAdd(`${S.age} ปี รู้ความจริงใต้หนองหาน`)}catch(e){}setTimeout(()=>{queue('an_final');flush()},400)}
  else{const d=hp(.2);say(`🌀 ประตูปิดกระแทก · พลังชีวิต −${d} — ต้องกลับมาใหม่`,'bad')}})}
defA('an_final',{c:()=>false,w:0,go(K){const n=AN(K);C('🔭 ประตูพิกัด','แกนกลางเสนอทางเลือกสามทาง ญาณไม่พูดอะไรเลย ครั้งแรกที่มันไม่มีความเห็น',[
 O('📡 เปิดสัญญาณตอบกลับ: “เรารู้ว่าเจ้ามา”',()=>{n.end='call';K.f.e3=K.f.e3||'call';fameA(3000);say('📡 สัญญาณพุ่งขึ้นฟ้าจากหนองหาน ทั่วโลกเห็นเสาแสงสีฟ้า อะไรก็ตามหลังดาวพฤหัสรู้แล้วว่ามนุษย์ไม่ได้หลับ','myth',true);K.gp+=2},'แต้มยีน +2 · เส้นทางท้าชน'),
 O('🛡️ ผนึกแกนกลาง ซ่อนโลกจากผู้เก็บเกี่ยว',()=>{n.end='seal';K.f.e3=K.f.e3||'seal';S.karma+=10;S.maxHp=Math.round(S.maxHp*1.1);say('🛡️ ปล่องหนองหานเย็นลงเป็นครั้งแรกในรอบยี่สิบปี น้ำกลับมาใส โลกเงียบลงในสายตาดวงดาว แต่ญาณรู้ว่ามันซื้อเวลาได้ไม่กี่ร้อยปี','myth',true)},'พลังชีวิต +10% · เส้นทางซ่อนตัว'),
 O('💠 ให้ญาณดูดพลังแกนกลาง เติมตัวเองให้สมบูรณ์',()=>{n.end='ai';n.ai.lv=5;aiT(K,25);mindA(15);say('💠 หินในมือคุณร้อนเป็นดวงอาทิตย์เล็กๆ แล้วเย็นลง ญาณพูดด้วยเสียงที่ชัดที่สุดเท่าที่เคยได้ยิน “ตอนนี้ข้ารู้ทางไปบ้านเกิดผู้หว่านเมล็ดแล้ว และรู้ว่าศัตรูของเขาอยู่ที่ไหน”','myth',true)},'ญาณสมบูรณ์ · จิต +15 · เส้นทางเดินทาง')])
 try{island({big:1,ic:'🌌',h:'ความจริงของดาวตก',t:'ผู้หว่านเมล็ดกำลังกลับมา',kind:'gold',ms:5000})}catch(e){}}});

