const DISN=[['🦊','ฟ้าครามแห่งเผ่าจิ้งจอกดารา','นักดาบจิ้งจอกเก้าหาง (ทำจากแสง)'],['🪨','ศิลาผู้เงียบงัน','ยักษ์หินที่พูดปีละคำ'],['🫧','ธาราน้อย','ลูกหลานนิลาที่ข้ามดาราจักรมาหาคุณ'],['🤖','หน่วย 0-ปลายฟ้า','จักรกลที่หนีออกจากเครือข่ายอัญญา'],['🔥','อัคนีผู้หิวโหย','ลูกผู้ดับดาวที่ไม่อยากดับดาว'],['🧒','ภูมิ ทายาทรุ่นที่ร้อย','ทายาทสายตรงคุณที่ตามรอยมาจากโลก'],['🦂','เขี้ยวสุดท้าย','เธรนรุ่นสุดท้ายที่ยังล่าเป็น'],['🌸','ซากุระดาว','หญิงสาวจากดาราจักรที่ไม่มีใครรู้จัก มีความลับ']];
def('u_disq',{c:()=>false,w:0,go(K){C('🏯 ตั้งสำนัก','จะเป็นเจ้าสำนักดาราได้ต้องมีศิษย์อย่างน้อย 3 คน ข่าวว่ามนุษย์ผู้ล้มผู้ดับดาวกำลังรับศิษย์แพร่ไปทั่วกลุ่มดาราจักร',[O('เปิดรับศิษย์ทั่วกลุ่มดาราจักร',()=>{if(!K.u.sect)K.u.sect='สำนักทะลุฟ้า';queue('e5_recruit');flush()}),O('ไว้ก่อน',()=>{})].filter(o=>!(mgAuto()&&o.t==='ไว้ก่อน')))}});
defU('e5_recruit',{c:K=>uDis(K).length<DISN.length,cd:3000,w:6,go(K){const nx=DISN.find(d=>!uDis(K).some(x=>x.n===d[1]));if(!nx)return;const tal=R(2,5);C(`🙇 ${nx[0]} ${nx[1]}`,`${nx[2]} คุกเข่าหน้าประตูสำนักมาสามร้อยปี ขอเป็นศิษย์ · พรสวรรค์ ${'★'.repeat(tal)}`,[
 O('ทดสอบก่อนรับ',()=>mgD(pick(MGL(5)),tal,`🙇 ทดสอบ${nx[1]}`,'ดูว่าศิษย์จะตามทันไหม ทำให้ดีเพื่อดึงศักยภาพเขาออกมา',sc=>{const t2=Math.min(5,tal+(sc>=.7?1:0));uDis(K).push({ic:nx[0],n:nx[1],r:nx[2],tal:t2,lv:1,ly:50,st:'on',j:S.age});if(!K.u.sect)K.u.sect='สำนักทะลุฟ้า';say(`🏯 <b>${nx[1]}</b> เป็นศิษย์คุณแล้ว${sc>=.7?' คุณเห็นแววที่คนอื่นไม่เห็น พรสวรรค์ +1':''}`,'epic');later(K,'e5_d_'+DISN.indexOf(nx),R(1,3))}),'มินิเกม'),
 O('รับทันที',()=>{uDis(K).push({ic:nx[0],n:nx[1],r:nx[2],tal,lv:1,ly:60,st:'on',j:S.age});if(!K.u.sect)K.u.sect='สำนักทะลุฟ้า';say(`🏯 ${nx[1]}ยิ้มกว้างที่สุดในรอบสามร้อยปี`,'good');later(K,'e5_d_'+DISN.indexOf(nx),R(1,3))}),
 O('ปฏิเสธ',()=>say('🚪 ศิษย์ลุกขึ้นแล้วเดินจากไปโดยไม่หันกลับ',''))])}},5);
const dArc=(i,ti,tx,opts)=>def('e5_d_'+i,{c:()=>false,w:0,go(K){const x=uDis(K).find(d=>d.n===DISN[i][1]&&d.st==='on');if(!x)return;C(ti,tx(x),opts(K,x))}});
dArc(0,'🦊 ฟ้าครามขอดวล',x=>`${x.n}ท้าคุณดวลต่อหน้าศิษย์ทั้งสำนัก “ข้าอยากรู้ว่าระยะห่างระหว่างเรายังไกลแค่ไหน”`,(K,x)=>[O('รับดวลเต็มกำลัง',()=>{x.ly+=15;x.lv=Math.min(10,x.lv+1);say(`⚔️ ${x.n}ล้มลงยิ้มทั้งน้ำตา “ยังไกลมาก ดีแล้ว”`,'good')}),O('ยอมแพ้ให้ศิษย์',()=>{x.ly-=10;say(`🦊 ${x.n}โกรธ “ท่านดูถูกข้า”`,'bad')}),O('ดวลแบบสอนไปด้วย',()=>mgD('beat',2,'🎵 ดวลแบบครู','แตะตามจังหวะ',sc=>{x.ly+=sc>=.5?25:10;x.lv=Math.min(10,x.lv+(sc>=.5?2:1));say(`🦊 ${x.n}เรียนรู้ในหนึ่งวันเท่ากับร้อยปี`,'epic')}),'มินิเกม')]);
dArc(4,'🔥 อัคนีหิว',x=>`${x.n}ลูกผู้ดับดาวเริ่มหิว ดาวรอบสำนักหรี่แสงลงทีละดวง เขาร้องไห้ “ข้าไม่อยากเป็นแบบพ่อ”`,(K,x)=>[O('สอนให้กินแสงช้าๆ จากดาวที่ตายแล้ว',()=>mgD('balance',3,'⚖️ คุมความหิวของอัคนี','ประคองให้อยู่ตรงกลาง',sc=>{if(sc>=.5){x.ly+=30;x.lv+=1;say('🔥 อัคนีกินแสงจากดาวตายแทนดาวเป็น คนแรกในเผ่าพันธุ์ที่ทำได้','myth',true);K.u.akn=1}else{x.ly-=10;say('🔥 ดาวสามดวงดับ อัคนีขังตัวเองในถ้ำ','bad')}}),'มินิเกม'),O('ผนึกพลังเขา',()=>{x.lv=Math.max(1,x.lv-2);x.ly-=15;say('🔒 อัคนีอ่อนลงแต่ปลอดภัย และไม่พูดกับคุณอีกพันปี','')}),O('ขับออกจากสำนัก',()=>{x.st='gone';S.karma-=10;say('🚪 อัคนีเดินออกไปในความมืด','bad');later(K,'e5_akn_back',4)})]);
dArc(5,'🧒 ทายาทรุ่นที่ร้อย',x=>`${x.n}เอาของบางอย่างมาให้ รูปถ่ายเก่าที่ส่งต่อกันในตระกูลมาร้อยรุ่น เป็นรูปคุณตอนเด็กกับแม่ในหลุมหลบภัย`,(K,x)=>[O('เก็บรูปไว้',()=>{x.ly+=30;mindA(30);say(`🖼️ คุณจำหน้าแม่ได้อีกครั้ง${uPage(K,'p2')}`,'myth',true)})]);
dArc(7,'🌸 ความลับของซากุระดาว',x=>`${x.n}สารภาพว่าเธอเป็นสายลับของสภาจักรวาล ส่งมาดูว่าคุณอันตรายไหม แต่เธออยากอยู่ต่อจริงๆ`,(K,x)=>[O('ให้อยู่ต่อ',()=>{x.ly+=40;K.u.ucIn=1;say('🌸 เธอส่งรายงานกลับสภาว่า “ไม่อันตราย แค่ดื้อ”','myth')}),O('ส่งกลับสภา',()=>{x.st='gone';say('🌸 เธอโค้งลาโดยไม่ร้องไห้ จนพ้นประตูไป','')})]);
[1,2,3,6].forEach(i=>dArc(i,`${DISN[i][0]} ${DISN[i][1]}`,x=>`${x.n}ไปทำภารกิจในดาราจักรใกล้เคียงแล้วกลับมาพร้อมเรื่องเล่า`,(K,x)=>[O('ฟังเรื่องเล่า',()=>{x.ly+=10;K.cores+=10;say(`${x.ic} ${x.n}นำแก่นอสูรกลับมาสิบก้อน และเรื่องตลกที่ไม่ตลกเลย`,'good')}),O('ส่งไปภารกิจยากกว่าเดิม',()=>{if(rnd()<.2+x.lv*.07){x.lv++;say(`${x.ic} ${x.n}สำเร็จและแข็งแกร่งขึ้น${uRew(K,.3)}`,'epic')}else{x.st='dead';say(`🕯️ ${x.n}ไม่กลับมา`,'bad')}},'เสี่ยง')]));
def('e5_surpass',{c:()=>false,w:0,go(K){const x=uDis(K).find(d=>d.sur===1&&d.st==='on');if(!x)return;x.sur=2;C(`⚔️ ${x.n}แซงหน้าคุณ`,`${x.n}ยืนอยู่หน้าคุณด้วยพลังที่เกือบเท่ากัน “ศิษย์ที่ดีต้องแซงครู ให้ข้าได้ลองไหม”`,[
 O('ดวลจริงจัง',()=>uFight(K,`⚔️ ดวลกับ${x.n}`,3,0,()=>{x.ly=100;say(`🙇 ${x.n}คุกเข่า “ยังอีกไกล ขอบคุณที่ไม่ออมมือ”`,'myth')},()=>{x.ly=100;say(`🌟 ${x.n}ชนะ คุณหัวเราะดังที่สุดในรอบล้านปี นี่คือความภูมิใจที่สุดของครู`,'myth',true)}),'ศึก 3 ช่วง'),
 O('มอบตำแหน่งเจ้าสำนักให้',()=>{x.ly=100;x.heir=1;S.karma+=15;say(`🏯 ${x.n}เป็นเจ้าสำนักรุ่นที่สอง คุณได้เวลาว่างครั้งแรกในรอบหมื่นปี`,'myth',true)}),
 O('ข่มเขาไว้ ยังไม่ถึงเวลา',()=>{x.ly-=40;if(x.ly<30){x.st='traitor';later(K,'e5_betray',2)}say(`😤 ${x.n}เงียบไป`,'bad')})])}});
def('e5_betray',{c:()=>false,w:0,go(K){const x=uDis(K).find(d=>d.st==='traitor');if(!x)return;C(`🗡️ ${x.n}ทรยศ`,`${x.n}พาศิษย์ครึ่งสำนักไปเข้ากับผู้ดับดาว “ท่านกลัวที่จะถูกแซง ข้าจะแซงท่านด้วยวิธีของข้า”`,[O('ตามไปล้างสำนัก',()=>uFight(K,`🗡️ ${x.n}`,3,0,()=>{x.st='dead';say(`🕯️ ${x.n}ตายในอ้อมแขนคุณ “…ข้าแค่อยากให้ท่านภูมิใจ”`,'myth',true)},()=>{const d=hp(.5);say(`🩸 พลังผู้ดับดาวทำให้${x.n}แข็งแกร่งกว่าที่คิด · พลังชีวิต −${d}`,'bad')}),'ศึก'),O('ปล่อยไป',()=>{S.karma-=5;say('🚪 สำนักเงียบลงครึ่งหนึ่ง','')})])}});
def('e5_akn_back',{c:()=>false,w:0,go(K){C('🔥 อัคนีกลับมา','อัคนีที่คุณขับออกไปกลับมาพร้อมผู้ดับดาวสามตัว แต่เขายืนขวางหน้าคุณ ไม่ใช่ขวางสำนัก “ข้าพาพวกมันมาคุย ไม่ได้พามาฆ่า”',[O('คุยกับผู้ดับดาว',()=>{S.karma+=20;K.u.akn=2;say('🌑 เป็นครั้งแรกที่ผู้ดับดาวคุยกับใคร พวกมันแค่หนาว และกินดาวเพื่ออุ่น','myth',true)}),O('สู้',()=>uFight(K,'🌑 ผู้ดับดาวสามตัว',3,0,()=>say(`🌑 ผู้ดับดาวถอยไป อัคนีมองคุณด้วยแววตาผิดหวัง${xp(80)}`,''),()=>{const d=hp(.5);say(`🩸 · พลังชีวิต −${d}`,'bad')}),'ศึก')])}});
def('e5_war',{c:()=>false,w:0,go(K){const D=uDis(K).filter(x=>x.st==='on');C('⚔️ สงครามกลุ่มดาราจักร',`จักรวรรดิดาวดำจากกำแพงใหญ่จักรวาลบุกกลุ่มดาราจักรท้องถิ่น ดาราจักรนับร้อยขอความช่วยเหลือ · ศิษย์พร้อมรบ ${D.length} คน`,[
 O('นำศิษย์ออกรบ',()=>uFight(K,'⚔️ ศึกกลุ่มดาราจักร',4,D.reduce((a,x)=>a+x.lv*.008,0),()=>{K.u.cw=1;K.xp=Math.max(K.xp,need(K));advance();say(`🏆 จักรวรรดิดาวดำถอยกลับไปหลังกำแพงใหญ่ ศิษย์ทุกคนกลับมาครบ${uRew(K,2)}`,'myth',true)},()=>{const x=pick(D);if(x&&rnd()<.3){x.st='dead';say(`🕯️ ${x.n}ตายในแนวหน้า`,'bad')}else{const d=hp(.4);say(`🩸 · พลังชีวิต −${d}`,'bad')}}),'ศึก 4 ช่วง'),
 O('ส่งศิษย์ไปรบแทน',()=>{const p=cl(.2+D.reduce((a,x)=>a+x.lv*.03,0),.1,.85);if(rnd()<p){K.u.cw=1;advance();say('🏆 ศิษย์คุณชนะสงครามเอง ชื่อสำนักดังไปทั่วจักรวาล','myth',true)}else say('🩸 ศิษย์แพ้กลับมา หลายคนบาดเจ็บ','bad')},'ลุ้น'),
 O('ไว้ก่อน',()=>{})].filter(o=>!(mgAuto()&&o.t==='ไว้ก่อน')))}});
def('e5_galq',{c:()=>false,w:0,go(K){C('🌌 สร้างดาราจักรของตัวเอง','ผู้คุมกลุ่มดาราจักรทุกคนต้องสร้างดาราจักรหนึ่งแห่งด้วยมือตัวเอง จากเมฆก๊าซเปล่าๆ ตรงหน้า',[
 O('เริ่มสร้าง',()=>{const G={};C('🌌 ดาวกลาง','จะให้อะไรอยู่ใจกลางดาราจักรคุณ',[['หลุมดำอ่อนโยน','🕳️'],['ดาวคู่สีทองกับฟ้า','☀️'],['ผลึกยักษ์ร้องเพลง','💎']].map(x=>O(`${x[1]} ${x[0]}`,()=>{G.star=x[0];C('🌱 เผ่าแรก','จะหว่านชีวิตแบบไหนเป็นเผ่าแรก',[['มนุษย์จากเซลล์คุณ'],['ลูกผสมนิลากับวรากร'],['สิ่งมีชีวิตใหม่ที่ไม่มีใครเคยเห็น']].map(y=>O(y[0],()=>{G.race=y[0];C('⚖️ กฎพิเศษ','ดาราจักรคุณจะมีกฎข้อเดียวที่ไม่มีที่ไหนมี',[['ไม่มีใครตายด้วยวัยชรา'],['ทุกสงครามต้องตัดสินด้วยเพลง'],['ทุกดาวที่ดับจะเกิดใหม่']].map(z=>O(z[0],()=>{G.rule=z[0];mgD('constel',4,'✨ ปั้นดาราจักร','แตะดาวตามลำดับให้ไว',sc=>{G.n='ดาราจักร'+pick(['ปลายฟ้า','ธารา','ดวงใจ','บ้าน','แม่'])+(sc>=.7?'ที่สมบูรณ์':'');G.civ=sc>=.5?3:1;G.age=0;K.u.gal=G;K.xp=Math.max(K.xp,need(K));advance();say(`🌌 <b>${G.n}</b> เริ่มหมุน — ${G.star}อยู่ใจกลาง ${G.race}ลืมตาดูโลกบนดาวดวงแรก และกฎ “${G.rule}” ถูกจารึกไว้ตลอดกาล`,'myth',true);later(K,'e5_gal1',2)})})))})))})))}),
 O('ไว้ก่อน',()=>{})].filter(o=>!(mgAuto()&&o.t==='ไว้ก่อน')))}});
def('e5_gal1',{c:()=>false,w:0,go(K){const G=K.u.gal;if(!G)return;G.age=(G.age|0)+2;G.civ=(G.civ|0)*3;C(`🙏 ${G.n}สวดหาคุณ`,`ในดาราจักรที่คุณสร้าง ${G.race}รุ่นแรกเริ่มมีศาสนา เทพเจ้าของพวกเขาคือ “ผู้หว่านจากฟ้า” ที่หน้าตาเหมือนคุณ`,[
 O('ลงไปพบพวกเขา',()=>{S.karma+=8;say(`👣 คุณเดินบนดาวที่ตัวเองสร้าง เด็กคนหนึ่งยื่นกระดาษที่เขียนเรื่องของคุณให้${uPage(K,'p1')}`,'myth',true)}),
 O('ปล่อยให้พวกเขาเติบโตเอง',()=>say('🌱 ร้อยล้านปีต่อมา พวกเขาส่งยานลำแรกออกมาหาคุณ','myth')),
 O('ทิ้งร่องรอยไว้ให้ค้นพบ',()=>{say(`🗿 คุณฝังหินที่มีตัวอักษรไทยไว้ใต้ภูเขา อีกหมื่นล้านปีจะมีใครสักคนขุดเจอ${uPage(K,'p1')}`,'myth')})])}});
def('e5_trial',{c:()=>false,w:0,go(K){C('🏛️ บททดสอบสภาจักรวาล','สภาจักรวาลประกอบด้วยผู้ที่อายุเท่าจักรวาลเก้าคน พวกเขาให้บททดสอบสามด่าน: พลัง ปัญญา และ “ความเป็นมนุษย์”',[
 O('รับบททดสอบ',()=>{let s0=0,k=0;const ST=[['swarm','💪 พลัง'],['quiz','🧠 ปัญญา'],['word','💗 ความเป็นมนุษย์']];const st=()=>mgD(ST[k][0],5,`🏛️ ${ST[k][1]}`,'ผ่านให้ได้',sc=>{s0+=sc;k++;if(k<3)return setTimeout(st,350);if(s0>=1.5||K.u.ucIn&&s0>=1){K.u.uc=1;K.xp=Math.max(K.xp,need(K));advance();say('🏛️ สภาจักรวาลลุกขึ้นยืน เก้าคนที่ไม่เคยลุกให้ใครมาตั้งแต่บิ๊กแบง','myth',true)}else say('🏛️ “ยัง” กลับมาใหม่ได้ทุกเมื่อ','')});st()},'มินิเกม 3 ด่าน'),
 O('ไว้ก่อน',()=>{})].filter(o=>!(mgAuto()&&o.t==='ไว้ก่อน')))}});
