def('e6_first',{c:()=>false,w:0,go(K){K.u.law=K.u.law||{};C('⚖️ สัมผัสกฎข้อแรก','ในความเงียบหลังสงคราม คุณเห็นเส้นด้ายบางๆ ถักจักรวาลไว้ เส้นหนึ่งสั่นตอบสนองคุณ',Object.keys(LAWS).map(k=>O(`${LAWS[k][0]} ${LAWS[k][1]}`,()=>mgD('rune',2,`✍️ อักขระ${LAWS[k][1]}`,'จำเส้นแล้วลากตาม',sc=>{K.u.law[k]=1;K.u.lf=k;K.u.lp=0;K.xp=Math.max(K.xp,need(K));advance();say(`⚖️ <b>เข้าใจ${LAWS[k][1]}ระดับ 1</b> โลกทั้งใบดูเปลี่ยนไปตั้งแต่วินาทีนั้น`,'myth',true)}),'มินิเกม')))}});
